const jobs = $input.all()
  .map(item => item.json ?? {})
  .filter(job => job.job_id || job.url);


/*
  Normalize fields that can accept multiple values.

  Example:
  "Mid, Senior"
*/
function normalizeMulti(value, allowedValues) {
  if (!value) {
    return '';
  }

  const values = Array.isArray(value)
    ? value
    : String(value).split(',');

  const normalized = values
    .map(v => String(v).trim())
    .filter(Boolean)
    .filter(v => allowedValues.includes(v));

  return [...new Set(normalized)]
    .join(', ');
}


/*
  Normalize fields that accept only one value.
*/
function normalizeSingle(value, allowedValues) {
  if (!value) {
    return '';
  }

  const normalized =
    String(value).trim();

  return allowedValues.includes(normalized)
    ? normalized
    : '';
}


return jobs.map(job => {

  const workMode = normalizeSingle(
    job.work_mode,
    [
      'Remote',
      'Hybrid',
      'On-site'
    ]
  );


  const payment = normalizeMulti(
    job.payment ?? job.payment_type,
    [
      'Hourly',
      'Fixed-price',
      'Weekly',
      'Monthly',
      'Annual',
      'Not specified'
    ]
  );


  const timeType = normalizeSingle(
    job.time_type,
    [
      'Part-time',
      'Full-time'
    ]
  );


  const jobType = normalizeMulti(
    job.job_type,
    [
      'Contract',
      'Internship',
      'Freelance',
      'Temporary',
      'PJ',
      'CLT',
      'Long-term'
    ]
  );


  const experience = normalizeMulti(
    job.experience,
    [
      'Senior',
      'Mid',
      'Specialist',
      'Junior',
      'Intern',
      'Lead'
    ]
  );


  const status =
    normalizeSingle(
      job.status,
      [
        'To do',
        'Applying',
        'Applied',
        'Closed',
        'Mismatch',
        'Not selected',
        'Selected',
        'Interview',
        'Offer',
        'Hired'
      ]
    ) || 'To do';


  const language = normalizeSingle(
    job.language,
    [
      'English',
      'Portuguese'
    ]
  );


  const match = normalizeSingle(
    job.match,
    [
      'Low',
      'Medium',
      'High'
    ]
  );


  const qualified = normalizeSingle(
    job.qualified,
    [
      'Yeap',
      'Nope'
    ]
  );


  return {
    json: {

      // A - Job ID
      job_id:
        String(
          job.job_id ||
          `url:${job.url}`
        ),

      // B - Status
      status,

      // C - Date Scraped
      date_scraped:
        job.date_scraped ?? '',

      // D - Source
      source:
        job.source ??
        job._source ??
        '',

      // E - Search Keyword
      search_keyword:
        job.search_keyword ?? '',

      // F - Date Posted
      date_posted:
        job.date_posted ?? '',

      // G - Title
      title:
        job.title ||
        'Not specified',

      // H - Work Mode
      work_mode:
        workMode,

      // I - URL
      url:
        job.url ?? '',

      // J - Company Name
      company_name:
        job.company_name ?? '',

      // K - Location
      location:
        job.location ??
        job.location_geo ??
        job.job_location ??
        '',

      // L - Description
      description:
        job.description ?? '',

      // M - Language
      language,

      // N - Payment
      payment,

      // O - Time Type
      time_type:
        timeType,

      // P - Job Type
      job_type:
        jobType,

      // Q - Experience
      experience,

      // R - Salary
      salary:
        job.salary ?? '',

      // S - Match
      match,

      // T - Qualified
      qualified,

      // U - Cover Letter
      cover_letter:
        job.cover_letter ?? '',

      // V - Notes
      notes:
        job.notes ?? '',

      // W - Interview At
      interview_at:
        job.interview_at ?? '',

      // X - Invite Meet
      invite_meet:
        job.invite_meet ?? '',

      // Y - Attended
      attended:
        job.attended === true ||
        String(job.attended ?? '')
          .toLowerCase() === 'true',


      // Internal workflow metadata
      posted_at:
        job.posted_at ?? '',

      scraped_at:
        job.scraped_at ?? ''
    }
  };
});

const job = $json ?? {};


/*
  Public template configuration.

  Replace this placeholder with the Google Sheets
  spreadsheet ID used as the job tracker.
*/
const SPREADSHEET_ID =
  'YOUR_GOOGLE_SHEET_ID';


/*
  Reference timezone used by the template.

  Users should change the workflow timezone and this
  value if their job tracker should follow another
  local timezone.
*/
const TIME_ZONE =
  'America/Sao_Paulo';


/*
  Monthly sheet names expected by the Google Sheets
  job tracker template.
*/
const MONTHS = [
  'JANEIRO',
  'FEVEREIRO',
  'MARÇO',
  'ABRIL',
  'MAIO',
  'JUNHO',
  'JULHO',
  'AGOSTO',
  'SETEMBRO',
  'OUTUBRO',
  'NOVEMBRO',
  'DEZEMBRO'
];


/*
  Resolve the target month from a valid timestamp.

  posted_at is stored internally as an ISO timestamp,
  so this is the preferred routing method.
*/
function monthNameFromDate(dateValue) {
  const date =
    new Date(dateValue);

  if (
    Number.isNaN(date.getTime())
  ) {
    return null;
  }

  const monthNumber =
    Number(
      new Intl.DateTimeFormat(
        'en-US',
        {
          timeZone: TIME_ZONE,
          month: '2-digit'
        }
      ).format(date)
    );

  return (
    MONTHS[monthNumber - 1] ??
    null
  );
}


/*
  Fallback for Date Scraped values formatted as:

  DD/MM/YYYY
  or
  DD/MM/YYYY HH:mm
*/
function monthNameFromFormattedDate(value) {
  const text =
    String(value ?? '').trim();

  const match =
    text.match(
      /^(\d{2})\/(\d{2})\/(\d{4})(?:\s+\d{2}:\d{2}(?::\d{2})?)?$/
    );

  if (!match) {
    return null;
  }

  const monthNumber =
    Number(match[2]);

  return (
    MONTHS[monthNumber - 1] ??
    null
  );
}


/*
  Monthly routing strategy:

  1. Prefer posted_at and store the job in the month
     when the LinkedIn posting was published.

  2. If posted_at is unavailable, fall back to
     Date Scraped.
*/
const targetSheet =
  (
    job.posted_at
      ? monthNameFromDate(
          job.posted_at
        )
      : null
  ) ||
  monthNameFromFormattedDate(
    job.date_scraped
  );


if (!targetSheet) {
  throw new Error(
    `Unable to determine the target monthly sheet. ` +
    `posted_at=${job.posted_at || 'empty'}; ` +
    `date_scraped=${job.date_scraped || 'empty'}`
  );
}


if (
  !MONTHS.includes(targetSheet)
) {
  throw new Error(
    `Invalid monthly sheet: ${targetSheet}`
  );
}


/*
  Job ID is stored in column A.

  Deduplication therefore checks column A across
  all 12 monthly sheets.
*/
const dedupeRanges =
  MONTHS.map(
    month =>
      `${month}!A:A`
  );


const rangesQuery =
  dedupeRanges
    .map(
      range =>
        `ranges=${encodeURIComponent(range)}`
    )
    .join('&');


/*
  One Google Sheets batchGet request checks the
  LinkedIn Job ID across all monthly tabs.
*/
const dedupeUrl =
  `https://sheets.googleapis.com/v4/spreadsheets/` +
  `${SPREADSHEET_ID}/values:batchGet?` +
  rangesQuery;


return [{
  json: {
    ...job,

    target_sheet:
      targetSheet,

    dedupe_url:
      dedupeUrl,

    /*
      Google Sheets target structure:
      columns A:Y = 25 columns.
    */
    append_range_encoded:
      encodeURIComponent(
        `${targetSheet}!A:Y`
      ),

    /*
      Exact Google Sheets column order.
    */
    row_values: [

      job.job_id ?? '',          // A - Job ID

      job.status ?? '',          // B - Status

      job.date_scraped ?? '',    // C - Date Scraped

      job.source ?? '',          // D - Source

      job.search_keyword ?? '',  // E - Search Keyword

      job.date_posted ?? '',     // F - Date Posted

      job.title ?? '',           // G - Title

      job.work_mode ?? '',       // H - Work Mode

      job.url ?? '',             // I - URL

      job.company_name ?? '',    // J - Company Name

      job.location ?? '',        // K - Location

      job.description ?? '',     // L - Description

      job.language ?? '',        // M - Language

      job.payment ?? '',         // N - Payment

      job.time_type ?? '',       // O - Time Type

      job.job_type ?? '',        // P - Job Type

      job.experience ?? '',      // Q - Experience

      job.salary ?? '',          // R - Salary

      job.match ?? '',           // S - Match

      job.qualified ?? '',       // T - Qualified

      job.cover_letter ?? '',    // U - Cover Letter

      job.notes ?? '',           // V - Notes

      job.interview_at ?? '',    // W - Interview At

      job.invite_meet ?? '',     // X - Invite Meet

      job.attended ?? false      // Y - Attended
    ]
  }
}];

const ctx =
  $('Prepare Monthly Row').item.json ?? {};

const valueRanges =
  Array.isArray($json.valueRanges)
    ? $json.valueRanges
    : [];

const existingIds =
  new Set();


/*
  Collect all LinkedIn Job IDs from column A
  across all 12 monthly sheets.
*/
for (const range of valueRanges) {
  const values =
    Array.isArray(range.values)
      ? range.values
      : [];

  for (const row of values) {
    const value =
      String(
        row?.[0] ?? ''
      ).trim();

    if (
      !value ||
      value === 'Job ID'
    ) {
      continue;
    }

    existingIds.add(value);
  }
}


const currentId =
  String(
    ctx.job_id ?? ''
  ).trim();


/*
  Find the column A response that belongs specifically
  to the monthly sheet where this job will be stored.
*/
const targetSheetName =
  String(
    ctx.target_sheet ?? ''
  )
    .trim()
    .toUpperCase();


const targetRange =
  valueRanges.find(range => {
    const rangeName =
      String(
        range.range ?? ''
      )
        .replace(/'/g, '')
        .toUpperCase();

    return rangeName.startsWith(
      `${targetSheetName}!A`
    );
  });


const targetValues =
  Array.isArray(targetRange?.values)
    ? targetRange.values
    : [];


/*
  Find the last row currently used in column A.

  Column A contains the Job ID and therefore acts
  as the reference column for row allocation.
*/
let lastUsedRow = 0;

for (
  let i = 0;
  i < targetValues.length;
  i++
) {
  const value =
    String(
      targetValues[i]?.[0] ?? ''
    ).trim();

  if (value) {
    lastUsedRow = i + 1;
  }
}


/*
  Row 1 contains the header.

  The first available data row is therefore row 2.
*/
const nextRow =
  Math.max(
    lastUsedRow + 1,
    2
  );


/*
  Build the exact A:Y range where the new job
  will be written if it passes the duplicate check.
*/
const writeRange =
  `${ctx.target_sheet}!A${nextRow}:Y${nextRow}`;


return [{
  json: {
    ...ctx,

    is_new:
      currentId !== '' &&
      !existingIds.has(currentId),

    duplicate_checked_across_12_months:
      true,

    next_row:
      nextRow,

    write_range:
      writeRange,

    write_range_encoded:
      encodeURIComponent(
        writeRange
      )
  }
}];

return [{
  json: {
    job_id: $json.job_id,
    target_sheet: $json.target_sheet,
    saved: false,
    reason: 'duplicate_job_id'
  }
}];

return [{
  json: {
    status: 'completed',
    message:
      'Job Saver finished. Job IDs were checked across all 12 monthly tabs.'
  }
}];

const original =
  $('Is New Job?').item.json ?? {};

const response =
  $json ?? {};

const html =
  typeof response.data === 'string'
    ? response.data
    : typeof response.body === 'string'
      ? response.body
      : '';


// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function decodeHtml(text = '') {
  return String(text)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCharCode(Number(n))
    )
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}


// --------------------------------------------------
// DESCRIPTION
// --------------------------------------------------

function extractDescription(html) {
  const match = html.match(
    /<div[^>]*class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i
  );

  return match
    ? decodeHtml(match[1])
    : '';
}


// --------------------------------------------------
// LINKEDIN CRITERIA
// --------------------------------------------------

function extractCriteria(html) {
  const criteria = {};

  const regex =
    /<li[^>]*class="[^"]*description__job-criteria-item[^"]*"[^>]*>([\s\S]*?)<\/li>/gi;

  let match;

  while (
    (match = regex.exec(html)) !== null
  ) {
    const block =
      match[1];

    const headerMatch =
      block.match(
        /<h3[^>]*class="[^"]*description__job-criteria-subheader[^"]*"[^>]*>([\s\S]*?)<\/h3>/i
      );

    const valueMatch =
      block.match(
        /<span[^>]*class="[^"]*description__job-criteria-text[^"]*"[^>]*>([\s\S]*?)<\/span>/i
      );

    if (
      !headerMatch ||
      !valueMatch
    ) {
      continue;
    }

    const key =
      decodeHtml(
        headerMatch[1]
      );

    const value =
      decodeHtml(
        valueMatch[1]
      );

    if (
      key &&
      value
    ) {
      criteria[key] =
        value;
    }
  }

  return criteria;
}


// --------------------------------------------------
// TARGET JOB HTML ONLY
// --------------------------------------------------

/*
  Keep only the section that belongs to the target job.

  This prevents the parser from detecting Remote,
  Hybrid, On-site, or other metadata from recommended
  jobs displayed later on the LinkedIn page.
*/

function extractTargetJobHtml(html) {
  const raw =
    String(html || '');

  const cutoffMarkers = [
    'find-a-referral',
    'people-also-viewed',
    'base-aside-card',
    'similar-jobs',
  ];

  let cutoff =
    raw.length;

  for (
    const marker
    of cutoffMarkers
  ) {
    const index =
      raw.indexOf(marker);

    if (
      index !== -1 &&
      index < cutoff
    ) {
      cutoff =
        index;
    }
  }

  return raw.slice(
    0,
    cutoff
  );
}


// --------------------------------------------------
// LANGUAGE
// --------------------------------------------------

function detectLanguage(text) {
  const value =
    String(text || '')
      .toLowerCase()
      .trim();

  if (!value) {
    return '';
  }

  const portugueseMarkers = [
    'experiência',
    'responsabilidades',
    'requisitos',
    'conhecimento',
    'conhecimentos',
    'desenvolvimento',
    'trabalho',
    'buscamos',
    'empresa',
    'equipe',
    'pessoa',
    'pessoas',
    'vaga',
    'tecnologia',
    'engenharia',
    'dados',
    'soluções',
    'projetos',
    'oportunidade',
    'inglês',
    'habilidades',
    'qualificações',
    'atividades',
    'benefícios',
    'profissional',
    'contribuir',
    'liderança',
    'ambiente',
  ];

  const englishMarkers = [
    'experience',
    'responsibilities',
    'requirements',
    'knowledge',
    'development',
    'work',
    'looking for',
    'company',
    'team',
    'candidate',
    'technology',
    'engineering',
    'data',
    'solutions',
    'projects',
    'opportunity',
    'english',
    'skills',
    'qualifications',
    'benefits',
    'professional',
    'leadership',
    'environment',
    'you will',
    'we are',
  ];

  let portugueseScore = 0;
  let englishScore = 0;

  for (
    const marker
    of portugueseMarkers
  ) {
    if (
      value.includes(marker)
    ) {
      portugueseScore++;
    }
  }

  for (
    const marker
    of englishMarkers
  ) {
    if (
      value.includes(marker)
    ) {
      englishScore++;
    }
  }

  if (
    portugueseScore >
      englishScore &&
    portugueseScore >= 2
  ) {
    return 'Portuguese';
  }

  if (
    englishScore >
      portugueseScore &&
    englishScore >= 2
  ) {
    return 'English';
  }

  return '';
}


// --------------------------------------------------
// TIME TYPE
// --------------------------------------------------

function detectTimeType(value) {
  const text =
    String(value || '')
      .toLowerCase();

  if (
    text.includes(
      'tempo integral'
    ) ||
    text.includes(
      'full-time'
    ) ||
    text.includes(
      'full time'
    )
  ) {
    return 'Full-time';
  }

  if (
    text.includes(
      'meio período'
    ) ||
    text.includes(
      'meio periodo'
    ) ||
    text.includes(
      'part-time'
    ) ||
    text.includes(
      'part time'
    )
  ) {
    return 'Part-time';
  }

  return '';
}


// --------------------------------------------------
// JOB TYPE
// --------------------------------------------------

function detectJobType(
  employmentRaw,
  description
) {
  const text =
    `${
      employmentRaw || ''
    }\n${
      description || ''
    }`
      .toLowerCase();

  const types = [];

  /*
    Add Job Type only when explicit evidence exists
    in the job posting.

    Full-time / Part-time are not Job Type values.
    Junior does not imply Internship.
  */

  if (
    /\bclt\b/i.test(text)
  ) {
    types.push('CLT');
  }

  if (
    /\bpj\b/i.test(text) ||
    /\bpessoa jurídica\b/i.test(text) ||
    /\bpessoa juridica\b/i.test(text)
  ) {
    types.push('PJ');
  }

  if (
    /\bfreelance\b/i.test(text) ||
    /\bfreelancer\b/i.test(text)
  ) {
    types.push(
      'Freelance'
    );
  }

  /*
    Internship is added only when there is explicit
    evidence of estágio / internship.

    Junior, Assistente, starting-career language,
    learning opportunities, or mentorship are not
    treated as Internship evidence.
  */
  if (
    /\bestágio\b/i.test(text) ||
    /\bestagio\b/i.test(text) ||
    /\binternship\b/i.test(text)
  ) {
    types.push(
      'Internship'
    );
  }

  if (
    /\btemporário\b/i.test(text) ||
    /\btemporario\b/i.test(text) ||
    /\btemporária\b/i.test(text) ||
    /\btemporaria\b/i.test(text) ||
    /\btemporary\b/i.test(text)
  ) {
    types.push(
      'Temporary'
    );
  }

  if (
    /\blong-term\b/i.test(text) ||
    /\blong term\b/i.test(text) ||
    /\blongo prazo\b/i.test(text)
  ) {
    types.push(
      'Long-term'
    );
  }

  if (
    /\bcontract\b/i.test(text) ||
    /\bcontractor\b/i.test(text) ||
    /\bcontrato\b/i.test(text)
  ) {
    types.push(
      'Contract'
    );
  }

  return [
    ...new Set(types)
  ].join(', ');
}


// --------------------------------------------------
// EXPERIENCE — MULTI-SELECT
// --------------------------------------------------

function detectExperience(value) {
  const text =
    String(value || '')
      .toLowerCase()
      .trim();

  if (!text) {
    return '';
  }

  /*
    LinkedIn may return combined seniority ranges such as:

    Pleno-sênior
    Pleno/Sênior
    Mid-Senior
    Mid/Senior

    Because Experience is a multi-select field,
    both levels are preserved.
  */
  const hasMid =
    text.includes(
      'pleno'
    ) ||
    /\bmid\b/i.test(text) ||
    text.includes(
      'mid-level'
    ) ||
    text.includes(
      'mid level'
    );

  const hasSenior =
    text.includes(
      'sênior'
    ) ||
    text.includes(
      'senior'
    );

  if (
    hasMid &&
    hasSenior
  ) {
    return 'Mid, Senior';
  }

  if (
    /\blead\b/i.test(text) ||
    text.includes(
      'tech lead'
    ) ||
    text.includes(
      'technical lead'
    ) ||
    text.includes(
      'líder'
    ) ||
    text.includes(
      'lider'
    )
  ) {
    return 'Lead';
  }

  if (
    text.includes(
      'sênior'
    ) ||
    text.includes(
      'senior'
    )
  ) {
    return 'Senior';
  }

  if (
    text.includes(
      'especialista'
    ) ||
    text.includes(
      'specialist'
    )
  ) {
    return 'Specialist';
  }

  if (
    text.includes(
      'pleno'
    ) ||
    /\bmid\b/i.test(text) ||
    text.includes(
      'mid-level'
    ) ||
    text.includes(
      'mid level'
    )
  ) {
    return 'Mid';
  }

  /*
    LinkedIn PT-BR may use "Assistente"
    for entry-level positions.
  */
  if (
    text.includes(
      'assistente'
    ) ||
    text.includes(
      'entry level'
    ) ||
    text.includes(
      'entry-level'
    ) ||
    text.includes(
      'associate'
    )
  ) {
    return 'Junior';
  }

  if (
    text.includes(
      'júnior'
    ) ||
    text.includes(
      'junior'
    )
  ) {
    return 'Junior';
  }

  if (
    text.includes(
      'estágio'
    ) ||
    text.includes(
      'estagio'
    ) ||
    /\bintern\b/i.test(text)
  ) {
    return 'Intern';
  }

  return '';
}


// --------------------------------------------------
// WORK MODE
// --------------------------------------------------

function detectWorkMode(
  targetHtml,
  description
) {
  const scopedHtml =
    String(
      targetHtml || ''
    );

  const descriptionText =
    String(
      description || ''
    );

  /*
    Analyze only the HTML that belongs to the target job.

    Recommended or related jobs must never be used
    as evidence for Work Mode.
  */

  const structuredPatterns = [
    /"workplaceType"\s*:\s*"([^"]+)"/i,
    /"workplaceTypes"\s*:\s*\[\s*"([^"]+)"/i,
    /"jobLocationType"\s*:\s*"([^"]+)"/i,
  ];

  for (
    const pattern
    of structuredPatterns
