function normalize(value = '') {
  return String(value)
    .replace(/\r/g, '')
    .replace(/\u00a0/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}


function normalizedMatch(value = '') {
  return String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}


function unique(values = []) {
  const seen = new Set();

  return values.filter(value => {
    const key =
      normalizedMatch(value)
        .replace(
          /[^\p{L}\p{N}]+/gu,
          ' '
        )
        .trim();

    if (
      !key ||
      seen.has(key)
    ) {
      return false;
    }

    seen.add(key);

    return true;
  });
}


