function topScored(
  values,
  scorer,
  limit
) {
  return values
    .map(
      (value, index) => ({
        value,
        index,
        score:
          scorer(value)
      })
    )
    .filter(
      item =>
        item.score > 0
    )
    .sort(
      (a, b) =>
        b.score -
          a.score ||
        a.index -
          b.index
    )
    .slice(
      0,
      limit
    )
    .map(
      item =>
        item.value
    );
}


