function buildCompactDescription(
  description
) {
  const original =
    normalize(description);

  if (!original) {
    return '';
  }


  const blocks =
    original
      .split(/\n{2,}/)
      .map(
        block =>
          block.trim()
      )
      .filter(Boolean);


  const sections = {
    responsibilities: [],
    requirements: [],
    preferred: [],
    general: []
  };


  let currentSection =
    null;


  for (
    const block
    of blocks
  ) {
    const detected =
      detectSection(block);


    if (detected) {
      currentSection =
        detected;

      continue;
    }


    if (
      currentSection ===
      'ignore'
    ) {
      continue;
    }


    /*
      When the parser is inside an explicit section,
      preserve useful content from that section.
    */
    if (
      currentSection ===
        'responsibilities' ||
      currentSection ===
        'requirements' ||
      currentSection ===
        'preferred'
    ) {
      const cleaned =
        block
          .replace(
            /^[•●▪◦*-]\s*/,
            ''
          )
          .trim();


      if (
        cleaned &&
        !isCorporateFluff(
          cleaned
        )
      ) {
        sections[
          currentSection
        ].push(
          cleaned
        );
      }


      continue;
    }


    /*
      Content outside explicit sections is preserved
      only as general fallback material.

      Deterministic scoring later decides whether
      it contains useful technical information.
    */
    if (
      !isCorporateFluff(
        block
      )
    ) {
      sections.general.push(
        block
      );
    }
  }


  let responsibilities =
    unique(
      sections.responsibilities
    );


  let requirements =
    unique(
      sections.requirements
    );


  let preferred =
    unique(
      sections.preferred
    );


  /*
    If the job description does not contain clear
    headings, deterministic scoring selects the most
    relevant responsibility-like blocks.
  */
  if (
    !responsibilities.length
  ) {
    responsibilities =
      topScored(
        sections.general,
        responsibilityScore,
        6
      );
  }


  /*
    Apply the same deterministic fallback strategy
    for requirements.
  */
  if (
    !requirements.length
  ) {
    requirements =
      topScored(
        sections.general,
        requirementScore,
        7
      );
  }


  /*
    Safety limits keep the compact description small
    enough to reduce downstream LLM token usage.
  */
  responsibilities =
    responsibilities.slice(
      0,
      7
    );


  requirements =
    requirements.slice(
      0,
      8
    );


  preferred =
    preferred.slice(
      0,
      5
    );


  const technologies =
    extractTechnologies(
      original
    );


  const output = [];


  if (
    responsibilities.length
  ) {
    output.push(
      'RESPONSIBILITIES:\n' +
      responsibilities
        .map(
          value =>
            `• ${value}`
        )
        .join('\n')
    );
  }


  if (
    requirements.length
  ) {
    output.push(
      'REQUIREMENTS:\n' +
      requirements
        .map(
          value =>
            `• ${value}`
        )
        .join('\n')
    );
  }


  if (
    technologies.length
  ) {
    output.push(
      'TECH / SKILLS:\n' +
      technologies.join(', ')
    );
  }


  if (
    preferred.length
  ) {
    output.push(
      'NICE TO HAVE:\n' +
      preferred
        .map(
          value =>
            `• ${value}`
        )
        .join('\n')
    );
  }


  /*
    Final fallback when no structured section could
    be generated.
  */
  if (
    !output.length
  ) {
    return sections.general
      .slice(
        0,
        8
      )
      .map(
        value =>
          `• ${value}`
      )
      .join('\n');
  }


  return output.join(
    '\n\n'
  );
}


