return jobs.map(item => {
  const job =
    item.json ?? {};


  const compactDescription =
    buildCompactDescription(
      job.description ?? ''
    );


  const updatedJob = {
    ...job,

    description:
      compactDescription ||
      job.description ||
      ''
  };


